-- Migration 034: Create Platform Revenue Ledger
-- Date: 2026-04-11
-- Purpose: Track ALL revenue generated by platform (70% revenue focus)
-- Target: $23K/month by Month 12, scaling to $230K/month by Month 24

-- Platform Revenue Ledger (Master record of ALL revenue)
CREATE TABLE IF NOT EXISTS platform_revenue_ledger (
  id SERIAL PRIMARY KEY,

  -- Revenue Source
  revenue_source VARCHAR(60) NOT NULL, -- barter_transaction_fees / labor_transaction_fees / verification_fees / escrow_fees / premium_listing_fees / facility_commissions / pharmacy_order_commissions / currency_conversion_fees

  -- Amount
  amount_ugx DOUBLE PRECISION NOT NULL,
  amount_ap INTEGER, -- If revenue was in Afya Points
  amount_local_currency DOUBLE PRECISION, -- If revenue was in local currency (NGN, KES, ZAR)
  local_currency_code VARCHAR(5),

  -- Transaction Reference
  user_id INTEGER, -- User who paid the fee
  transaction_id INTEGER, -- Reference to the transaction that generated revenue
  transaction_type VARCHAR(40), -- barter_exchange / labor_booking / pharmacy_order / facility_service

  -- Revenue Attribution
  country_code VARCHAR(5), -- Which country generated this revenue
  facility_id INTEGER, -- If facility/pharmacy commission
  partner_revenue_share_ugx DOUBLE PRECISION, -- Partner's share of revenue (if applicable)

  -- Date
  revenue_date DATE NOT NULL,
  month DATE NOT NULL, -- YYYY-MM-01 for aggregation
  quarter VARCHAR(10), -- Q1 2026, Q2 2026, etc.
  year INTEGER,

  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  FOREIGN KEY (country_code) REFERENCES countries_supported(country_code),
  FOREIGN KEY (facility_id) REFERENCES facility_partners(id) ON DELETE SET NULL
);

-- Monthly Revenue Summary (Aggregated by month and source)
CREATE TABLE IF NOT EXISTS monthly_revenue_summary (
  id SERIAL PRIMARY KEY,
  month DATE NOT NULL, -- YYYY-MM-01

  -- Revenue by Source
  barter_fees_ugx DOUBLE PRECISION DEFAULT 0,
  labor_fees_ugx DOUBLE PRECISION DEFAULT 0,
  verification_fees_ugx DOUBLE PRECISION DEFAULT 0,
  escrow_fees_ugx DOUBLE PRECISION DEFAULT 0,
  premium_listing_fees_ugx DOUBLE PRECISION DEFAULT 0,
  facility_commissions_ugx DOUBLE PRECISION DEFAULT 0,
  pharmacy_commissions_ugx DOUBLE PRECISION DEFAULT 0,
  currency_conversion_fees_ugx DOUBLE PRECISION DEFAULT 0,

  -- Total
  total_revenue_ugx DOUBLE PRECISION DEFAULT 0,
  total_revenue_usd DOUBLE PRECISION, -- Converted to USD for reporting

  -- Transaction Counts
  total_transactions INTEGER DEFAULT 0,
  barter_transactions INTEGER DEFAULT 0,
  labor_transactions INTEGER DEFAULT 0,
  pharmacy_orders INTEGER DEFAULT 0,
  facility_services INTEGER DEFAULT 0,

  -- Revenue per Transaction (KPI)
  avg_revenue_per_transaction_ugx DOUBLE PRECISION,

  -- Country Breakdown (Top 5 countries by revenue)
  top_country_1_code VARCHAR(5),
  top_country_1_revenue_ugx DOUBLE PRECISION,
  top_country_2_code VARCHAR(5),
  top_country_2_revenue_ugx DOUBLE PRECISION,
  top_country_3_code VARCHAR(5),
  top_country_3_revenue_ugx DOUBLE PRECISION,

  calculated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (month)
);

-- Country Revenue Summary (Revenue by country by month)
CREATE TABLE IF NOT EXISTS country_revenue_summary (
  id SERIAL PRIMARY KEY,
  country_code VARCHAR(5) NOT NULL,
  month DATE NOT NULL,

  total_revenue_ugx DOUBLE PRECISION DEFAULT 0,
  total_revenue_local_currency DOUBLE PRECISION DEFAULT 0,
  local_currency_code VARCHAR(5),

  barter_fees_ugx DOUBLE PRECISION DEFAULT 0,
  labor_fees_ugx DOUBLE PRECISION DEFAULT 0,
  total_transactions INTEGER DEFAULT 0,

  -- User Metrics
  active_users INTEGER DEFAULT 0, -- Users who transacted this month
  new_users INTEGER DEFAULT 0, -- First-time users this month

  calculated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

  FOREIGN KEY (country_code) REFERENCES countries_supported(country_code),
  UNIQUE (country_code, month)
);

-- Revenue Targets (Monthly/quarterly goals)
CREATE TABLE IF NOT EXISTS revenue_targets (
  id SERIAL PRIMARY KEY,
  target_period VARCHAR(20) NOT NULL, -- YYYY-MM (monthly) or Q1 2026 (quarterly)
  target_type VARCHAR(40), -- monthly / quarterly / annual

  -- Target Amounts
  target_revenue_ugx DOUBLE PRECISION NOT NULL,
  target_revenue_usd DOUBLE PRECISION,

  -- Target Breakdown
  target_barter_fees_ugx DOUBLE PRECISION,
  target_labor_fees_ugx DOUBLE PRECISION,
  target_facility_commissions_ugx DOUBLE PRECISION,

  -- Target Metrics
  target_transactions INTEGER,
  target_active_users INTEGER,
  target_countries INTEGER, -- How many countries should be active

  -- Actuals (Updated monthly)
  actual_revenue_ugx DOUBLE PRECISION DEFAULT 0,
  actual_transactions INTEGER DEFAULT 0,
  actual_active_users INTEGER DEFAULT 0,

  -- Achievement
  achievement_pct DOUBLE PRECISION, -- (actual / target) × 100
  is_achieved BOOLEAN DEFAULT FALSE,

  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

  UNIQUE (target_period)
);

